def Saisie():
    b = False
    while not (b) :
        ch=str(input("Donner une chaine: "))
        b = verif(ch)
    return ch

def verif(ch):
    i = -1
    ok = True
    while ok and i < len(ch)-1 :
        i += 1
        ok = ch[i] in {"M","C","D","L","X","V","I"}
    return ok

def convert(x):
    if x ==  "M" :
        r = 1000
    elif x == "D" :
        r = 500
    elif x == "C" :
        r = 100
    elif x == "L" :
        r = 50
    elif x == "X" :
        r = 10
    elif x == "V" :
        r = 5
    elif x == "I" :
        r = 1
    elif x ==" " :
        r = 0
    return r

def Romain(ch):
    R = 0
    ch = ch + " "
    for i in range(len(ch)-1):
        a = convert(ch[i])
        b = convert(ch[i+1])
        if  a < b :
            a = -a
        R += a
    return R
  
def Afficher(R):
    print(R)
            
    
